// Parse the HuggingFace Inference API response
const data = $input.all();
const results = [];

for (const item of data) {
  const json = item.json;

  // Handle error responses
  if (json.error) {
    results.push({
      json: {
        output: `⚠️ HuggingFace API Error: ${json.error}`,
        model: 'openai/gpt-oss-20b',
        status: 'error'
      }
    });
    continue;
  }

  // The Inference API returns an array with generated_text
  let generatedText = '';
  if (Array.isArray(json)) {
    generatedText = json[0]?.generated_text || '';
  } else if (json.generated_text) {
    generatedText = json.generated_text;
  } else if (Array.isArray(json.body)) {
    generatedText = json.body[0]?.generated_text || '';
  } else if (typeof json === 'string') {
    generatedText = json;
  } else {
    // Fallback: stringify the whole response
    generatedText = JSON.stringify(json, null, 2);
  }

  results.push({
    json: {
      output: generatedText.trim(),
      model: 'openai/gpt-oss-20b',
      status: 'success'
    }
  });
}

return results;

